import type { GetMyFiles } from "wasp/server/operations/queries";

export const getMyFiles: GetMyFiles<void, unknown> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.File.findMany({
    where: { userId: context.user.id },
    orderBy: { createdAt: "desc" },
  });
};

